import sys
from Bio import SeqIO

def find_longest_orf(sequence):
    """Find the longest ORF in the given sequence (ATG to first in-frame stop codon)."""
    longest_orf = None
    seq_len = len(sequence)

    for frame in range(3):
        seq = sequence[frame:]
        i = 0
        while i < len(seq) - 2:
            codon = seq[i:i+3]
            if codon == 'ATG':
                j = i
                while j < len(seq) - 2:
                    stop_codon = seq[j:j+3]
                    if stop_codon in ('TAA', 'TAG', 'TGA'):
                        orf_length = j - i + 3
                        orf_start = i + 1
                        orf_end = j + 2
                        if longest_orf is None or orf_length > longest_orf[2]:
                            longest_orf = (orf_start, orf_end, orf_length)
                        break
                    j += 3
            i += 3

    return longest_orf

def get_reverse_complement(seq):
    """Get the reverse complement of a DNA sequence."""
    complement = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
    return ''.join(complement.get(base, base) for base in reversed(seq))

if len(sys.argv) < 2:
    sys.exit(1)

record = SeqIO.read(sys.argv[1], "fasta")
sequence = str(record.seq).upper()
seq_length = len(sequence)

# Forward strand ORF
forward_orf = find_longest_orf(sequence)

# Reverse strand ORF
reverse_seq = get_reverse_complement(sequence)
reverse_orf = find_longest_orf(reverse_seq)

# Determine longest ORF
longest = None
if forward_orf and reverse_orf:
    longest = forward_orf if forward_orf[2] >= reverse_orf[2] else reverse_orf
elif forward_orf:
    longest = forward_orf
elif reverse_orf:
    longest = reverse_orf

if longest:
    start, end, length = longest
    if longest == forward_orf:
        print(f"{start} {end} + {length}")
    else:
        # Convert reverse strand coordinates to forward strand
        fwd_start = seq_length - end + 1
        fwd_end = seq_length - start + 1
        print(f"{fwd_start} {fwd_end} - {length}")

