import sys

def main():
    if len(sys.argv) < 2:
        print("reads=0 pass_q20=0 mean_q=0.00")
        return

    filepath = sys.argv[1]
    total_reads = 0
    pass_q20 = 0
    sum_means = 0.0

    try:
        with open(filepath, 'r') as f:
            while True:
                header = f.readline()
                if not header:
                    break
                seq = f.readline()
                plus = f.readline()
                qual = f.readline()

                if not qual:
                    break

                qual_str = qual.strip()
                if not qual_str:
                    continue

                # Calculate mean quality for this read (Phred+33)
                q_sum = sum(ord(c) - 33 for c in qual_str)
                read_mean = q_sum / len(qual_str)

                total_reads += 1
                if read_mean >= 20:
                    pass_q20 += 1
                sum_means += read_mean
    except Exception:
        pass

    if total_reads > 0:
        mean_q = sum_means / total_reads
    else:
        mean_q = 0.0

    print(f"reads={total_reads} pass_q20={pass_q20} mean_q={mean_q:.2f}")

if __name__ == "__main__":
    main()
